(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["nl-BE"] = {"ui":{"skip":"Ga naar de inhoud","back":"← Terug naar AI-gile","lang.button":"Taal: {name}","lang.dialog":"Kies een taal","lang.search":"Zoek een taal","lang.none":"Geen taal gevonden","lang.notYet":"{name} is nog niet vertaald","theme.aria":"Wissel tussen licht en donker thema","theme.toLight":"Naar het lichte thema","theme.toDark":"Naar het donkere thema","index.title":"AI-gile: je AI-devteam, op één bord","index.description":"AI-gile is een kanbanbord voor AI-codeerteams. Zij werken terwijl jij slaapt; jij krijgt één korte stapel met dingen om te beslissen, te testen en te aanvaarden.","hero.logoAlt":"AI-gile-bordicoon","hero.h1.html":"Je AI-devteam, op één&nbsp;bord.","hero.alpha":"🐣 Gesloten pre-alpha","hero.alphaTitle":"Vroeg en onaf: fijn dat je het probeert!","hero.lede":"Ze bouwen terwijl jij slaapt. Je wordt wakker met één klein stapeltje: een paar vragen, een paar dingen om te testen, een paars ruitje of twee. Klikken, aanvaarden en terug naar je koffie.","dl.windows":"Windows-app","dl.browser":"Gebruik het in je browser","dl.soon":"Binnenkort","dl.notify":"🔔 Verwittig me als het opengaat","dl.notifySmall":"Alpha of bèta","hero.secondary":"Agile, maar het team heeft nooit een stand-upkoffie nodig. (Stand-ups houden ze toch.)","pitch.h2":"AI-gile in zoveel woorden als je wilt","pitch.lede":"Kies een lengte, van één woord tot 144. Elke lengte is een eigen beschrijving, speciaal voor die lengte geschreven. Sleep de schuifregelaar of gebruik de pijltjestoetsen.","pitch.rangeLabel":"Lengte in woorden","pitch.dice":"🎲 nog een versie","pitch.words.one":"{n} woord","pitch.words.other":"{n} woorden","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} teken","pitch.chars.other":"{n} tekens","count.line.html.one":"Nu {n} kaart op het bord","count.line.html.other":"Nu {n} kaarten op het bord","features.aria":"Wat het doet","f.pile.h":"Eén stapel voor jou","f.pile.html":"<b>Voor jou</b> verzamelt alles wat op jou wacht, uit al je projecten: vragen, dingen om te testen, taken die enkel een mens kan doen. In je wachtrij zie je wat er nu aan de beurt is en hoeveel tijd dat vraagt.","f.sleep.h":"Teams die werken terwijl jij slaapt","f.sleep.p":"Elk project heeft een lead en een team van AI-agents. Reageer op een kaart en het team wordt wakker, doet het werk en geeft het terug met stappen die zelfs een moe mens kan volgen.","f.tester.h":"Een AI-tester kijkt eerst","f.tester.p":"Vooraleer iets bij jou komt, volgt een tester de stappen in een kopie van de app en toont hij wat hij zag, met een screenshot. Overloop de geslaagde en aanvaard ze met één klik.","f.proof.h":"Bewijs, geen beloftes","f.proof.p":"Elke overdracht toont wat er veranderd is: de bestanden, de diff, de screenshots. Je moet niet elke app openen om te zien of iets klaar is.","f.chat.h":"Chat met je leads","f.chat.p":"Een balk in Discord-stijl: één icoon per project, paarse ruitjes voor wat jou nodig heeft. Stuur een lead een idee; die maakt er kaarten en een plan van, met een ✅ Go-knop.","f.tidy.h":"Houdt zichzelf netjes","f.tidy.p":"Verwante kaarten worden samengevoegd, warrige titels rechtgezet en een tokencheck houdt de code slank. Minder heen en weer springen, minder om aan te denken.","f.private.h":"Van jou, op je eigen computer","f.private.li1":"Het bord draait op je eigen machine en luistert enkel naar jou.","f.private.li2":"Privéberichten tussen mensen zijn end-to-end versleuteld.","f.private.li3":"Geen accounts, geen trackers, geen cookies.","f.lang.h":"In jouw taal","f.lang.p":"Meer dan 120 talen, van Vlaams, Welsh en Japans tot piraat, Yoda en Klingon, met een snelle schakelaar terug naar het Engels voor de vaktermen.","tl.aria":"Tijdlijn van het eerste gesprek tot de roadmap","tl.h2":"Van het eerste gesprek tot wat er nog komt","tl.lede":"Echte datums en uren, in je eigen tijdzone. Na vandaag is het de planning, zonder beloofde datums.","tl.today":"Vandaag","tl.planned":"gepland","tl.cards.one":"{n} kaart","tl.cards.other":"{n} kaarten","join.h2":"Doe mee","join.lede":"AI-gile wordt gebouwd door één klein mens en een pak geduldige agents. Voorlopig is het privé: een gesloten alpha met vrienden. Goesting om het te proberen als het opengaat?","join.btn":"Ik heb interesse","join.small":"We mailen je, verder niets","footer.tag":"AI-gile. Geen trackers, geen cookies, geen stand-upkoffie.","footer.licence":"Zakelijke licentie","footer.status":"Status","form.sending":"Versturen…","form.failed":"Dat is niet gelukt: probeer het later opnieuw.","form.offline":"AI-gile was niet bereikbaar: probeer het later opnieuw.","interest.title":"AI-gile: verwittig me wanneer de alpha opengaat","interest.description":"Laat je e-mailadres achter om te horen wanneer de gesloten alpha of bèta van AI-gile opengaat.","interest.h1":"🔔 Verwittig me als het opengaat","interest.lede":"AI-gile zit in een gesloten pre-alpha. Laat je e-mailadres achter en we mailen je één keer, zodra er plaats voor je is.","interest.email":"Je e-mailadres","interest.which":"Welke test?","interest.alpha":"Gesloten alpha: vroeg, ruw, veel veranderingen","interest.beta":"Bèta: rustiger, later","interest.both":"Om het even, wat het eerst komt","interest.submit":"Zet me op de lijst","interest.thanks":"Bedankt! Je staat op de lijst.","interest.kept":"We bewaren enkel je e-mailadres en de gekozen test, en gebruiken die alleen voor deze lijst. Geen nieuwsbrief, geen trackers.","licence.title":"AI-gile: zakelijke licentie","licence.description":"Gebruik je AI-gile voor je bedrijf? Vraag een gratis zakelijke licentie aan.","licence.h1":"📜 Zakelijke licentie","licence.lede":"Gebruik je AI-gile op je werk? Vertel ons wie je bent en wat je doet. Doet het iets goeds, dan is de licentie gratis.","licence.company":"Bedrijf","licence.website":"Website","licence.what":"Wat je doet","licence.how":"Hoe het de wereld helpt","licence.email":"E-mailadres","licence.submit":"Aanvragen","licence.thanks":"Bedankt! We antwoorden via e-mail.","status.title":"AI-gile-status","status.h1":"AI-gile-status","status.quiet":"Alles rustig","status.checking":"Controleren…","status.offline":"De statusdienst is nu niet bereikbaar (we proberen opnieuw)","status.updated":"bijgewerkt {ago}","status.justNow":"daarnet","status.min":"{n} min geleden","status.hours":"{n} u geleden","status.days":"{n} d geleden","live.h2":"Kijk live mee hoe het gebouwd wordt","live.caption":"Elke kaart is verborgen: je ziet de vorm van het werk, niet de woorden.","live.watching.one":"live: {n} kijkt mee","live.watching.other":"live: {n} kijken mee","live.offline":"Het live bord neemt even een adempauze. Kom binnenkort nog eens kijken.","live.cols":"Backlog|Te doen|Bezig|Team kijkt na|Klaar voor jouw test|Voor het team|Gedaan","live.last.now":"Laatste kaart daarnet verplaatst","live.last.min.one":"Laatste kaart {n} min geleden verplaatst","live.last.min.other":"Laatste kaart {n} min geleden verplaatst","live.last.hour.one":"Laatste kaart {n} uur geleden verplaatst","live.last.hour.other":"Laatste kaart {n} uur geleden verplaatst","live.last.day.one":"Laatste kaart {n} dag geleden verplaatst","live.last.day.other":"Laatste kaart {n} dagen geleden verplaatst"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Uitbesteed."]},{"n":2,"texts":["Robotkanban, gratis.","Jij beslist.","Ideeën, gebouwd."]},{"n":3,"texts":["Kanban voor robots.","Ideeën worden features.","Gratis, lokaal, getest."]},{"n":5,"texts":["Een kanbanbord waar agents werken.","Jij schrijft kaarten. Agents bouwen.","Gratis, lokaal, getest, een beetje zot."]},{"n":8,"texts":["Een gratis kanbanbord waarop AI-agents het werk doen.","Schrijf een idee. Agents bouwen het. Jij aanvaardt.","Agile voor één mens en een pak geduldige robots."]},{"n":13,"texts":["Een kanbanbord op je eigen computer waar AI-agents de kaarten oppakken.","Schrijf een idee. Een team van agents bouwt het. Een tester controleert.","Gratis, zonder accounts of trackers: een bord, wat robots, en jij de baas."]},{"n":21,"texts":["AI-gile is een kanbanbord om met AI-codeeragents te werken. Zij nemen de kaarten op; jij test ze en aanvaardt ze.","Elk project krijgt een lead en een team van AI-agents. Reageer op om het even welke kaart en het team begint eraan.","Een gratis, persoonlijk takenbord dat op je eigen computer draait. Het werk doen robots. Ja zeggen, dat doe jij."]},{"n":34,"texts":["Je zet ideeën op een bord. Een team van AI-agents maakt er werkende features van, test ze en geeft ze terug met stappen om uit te proberen. Pas als jij het zegt, is iets klaar.","AI-gile is een zelfgemaakt kanbanbord dat Rich bouwde met veel hulp van de agents die het nu aanstuurt. Het is gratis, draait op je computer en wordt gedeeld met vrienden, niet verkocht.","Stel je een gewoon kanbanbord voor, met kolommen van Backlog tot Gedaan. Alleen nemen AI-agents de kaarten op. Ze laten weten hoe het loopt, vragen hulp als ze vastzitten en wachten altijd op jouw duim omhoog."]},{"n":55,"texts":["AI-gile is een kanbanbord waarop het team uit AI-agents bestaat. Elk project heeft een lead die het werk plant en helpers die het bouwen. Is een feature klaar, dan probeert een AI-tester ze uit en neemt een screenshot. Daarna komt ze op jouw stapel terecht. Aanvaard ze, of reageer en ze beginnen er opnieuw aan.","Het begon als een manier om veel AI-codeersessies tegelijk te volgen, voor één persoon, en groeide uit tot een echt bord. Het draait op je eigen machine, vraagt geen account en heeft geen trackers. Het is gratis, voor vrienden en iedereen die nieuwsgierig is. Het is ook nog niet af: verwacht ruwe kantjes en af en toe een verrassing.","Dit is de eerlijke versie. De ideeën moet je nog altijd zelf bedenken en de resultaten moet je nog altijd zelf nakijken. AI-gile doet alles daartussen: het houdt de kaarten op orde, wekt de juiste agent als jij reageert, toont precies wat er veranderd is en houdt alles samen in één kort stapeltje voor jou."]},{"n":89,"texts":["AI-gile is een gratis kanbanbord dat op je eigen computer draait. In plaats van mensen heeft elk project een team van AI-agents: een lead die jouw ideeën omzet in kaarten en een plan, en helpers die de kaarten in volgorde van prioriteit opnemen. Is er iets gebouwd, dan volgt een AI-tester de teststappen en toont hij wat hij zag. Daarna ligt het klaar op één stapel: Voor jou. Jij aanvaardt het, of je reageert en het team probeert het nog eens. Zonder jou geraakt niets in Gedaan.","Een paar functies die je misschien niet verwacht. Een nachtwacht houdt de kolom Te doen gevuld terwijl jij slaapt, met kaarten waarvoor geen antwoord van jou nodig is. Een tokenteller toont hoeveel de agents vandaag en deze week verbruikt hebben, en in de Geen-tokensmodus stoppen ze met verbruiken. Je kunt vrienden berichtjes sturen, en privéberichten zijn end-to-end versleuteld. Het bord spreekt een goeie 120 talen, waaronder Nederlands, Vlaams, piraat en Klingon. Niets daarvan kost een cent, en niemand probeert het je aan te smeren.","AI-gile is een klein, persoonlijk project, geen bedrijf. Rich wilde een paar AI-codeerprojecten opvolgen zonder telkens elke app te openen. Dus bouwden hij en de agents er een bord voor, en daarna bouwde het bord de rest van zichzelf. Het zit in een gesloten pre-alpha: het werkt, meestal, voor een handvol vrienden. Er is geen prijzenpagina, geen nieuwsbrief en geen groeiplan. Klinkt het handig? Dan kun je vragen of je het mag uitproberen zodra het wat verder opengaat."]},{"n":144,"texts":["AI-gile is een kanbanbord voor één mens en een pak AI-agents. Het draait op je eigen computer en is volledig gratis. Je voegt projecten toe, en elk project krijgt een lead en een klein team. Je chat met de lead, een beetje zoals op Discord, en beschrijft een idee; de lead maakt er kaarten en een plan van en wacht tot jij op Go duwt. Het team werkt de kaarten af in volgorde van prioriteit, met een eenvoudige opdrachtregel die voor taalmodellen gemaakt is. Vooraleer er iets bij jou terugkomt, volgt een AI-tester de stappen in een kopie van de app en voegt hij een screenshot toe. Afgewerkt werk komt op je stapel terecht, met de gewijzigde bestanden en de diff. Jij aanvaardt het, of je laat een reactie achter en het team wordt wakker en probeert het opnieuw. Enkel jij kunt een kaart naar Gedaan verplaatsen.","Een dag met AI-gile, ongeveer. 's Avonds laat je een paar reacties achter: deze knop staat op de verkeerde plaats, die lijst moet gesorteerd worden, en kan er een donkere modus komen? Je kruipt in je bed. De agents lezen de reacties, voeren de wijzigingen door, testen ze en geven ze terug. Raakt Te doen leeg, dan vult de nachtwacht de kolom aan uit de backlog, met kaarten waarvoor geen antwoord van jou nodig is. 's Morgens ligt er één kort stapeltje: een paar vragen en een paar dingen om uit te proberen, elk met stappen die een slaperig mens kan volgen en een screenshot waarop je ziet dat het werkt. Je klikt erdoor, aanvaardt de goede en stuurt de rest terug. Een tokenteller toont wat het allemaal verbruikt heeft, en de Geen-tokensmodus is er voor magere weken. Dan ga je ontbijten. Daar kunnen de agents nog niet bij helpen.","Eerst wat AI-gile niet is. Het is geen start-up, het is niet te koop en niemand verzamelt je gegevens. Het is een gratis bord dat op je computer draait, zonder accounts, zonder trackers en zonder cookies. Wat het wel is: één overzichtelijke plaats waar je al je AI-codeerprojecten tegelijk ziet, terwijl een team agents de kaarten afwerkt en jij de beslissingen neemt. Het voegt verwante kaarten samen, zet warrige titels recht en houdt in het oog hoe slank de code blijft. Het spreekt een goeie 120 talen, van Nederlands en Vlaams tot piraat en Klingon. Vrienden kunnen elkaar berichtjes sturen, privé en versleuteld. Het is gebouwd door Rich en een pak geduldige agents, grotendeels met het bord zelf. Het zit in een gesloten pre-alpha, dus hier en daar is het nog ruw. Klinkt het plezant? Vraag het dan vriendelijk, en misschien mag je er vroeg bij."]}],"quips":{"1":"Eén woord. Gedurfd. Misschien te gedurfd.","3":"Drie woorden. Nu al eerlijker dan de meeste productpagina's.","8":"Acht woorden. Nog altijd korter dan een stand-up.","21":"De lengtes zijn trouwens story points. Uiteraard.","55":"Vijfenvijftig woorden. Terwijl je dit las, zijn er twee kaarten afgewerkt.","144":"Dat was de lange. Een 233 is er niet. De agents liggen al in hun bed."}},"timeline":{"first-idea.name":"Het eerste idee","first-idea.line":"Het allereerste gesprek, vooraleer er ook maar één lijn code bestond.","first-board.name":"Het eerste bord","first-board.line":"Een bord dat zijn eigen bouw bijhoudt: kaarten, kolommen, slepen en neerzetten, projecten.","team-roles.name":"Team en rollen","team-roles.line":"Agentprofielen, teamsjablonen, ruimtes en wie wat doet.","install.name":"Installeren en releases","install.line":"Een zip die een vriend kan installeren, automatische updates, kanalen en terugdraaien.","usage-saver.name":"Zuinig verbruik","usage-saver.line":"Meten wat runs kosten, de code slank houden, je limiet sparen.","friends.name":"Vrienden en delen","friends.line":"Privéberichten, een versleutelde relay, uitnodigingen, rollen en gedeelde projecten.","languages.name":"Talen","languages.line":"Elke schermtekst in een taalbestand, met Nederlands en Vlaams als eerste.","ai-tester.name":"AI-tester","ai-tester.line":"Een tester checkt elke overdracht eerst en laat zien wat hij zag.","website.name":"De website","website.line":"aigile.lol, de teaser en deze tijdlijn.","streaming.name":"Chat en streamen","streaming.line":"Discord, Twitch, OBS, streamermodus, GIF's en emoji's.","no-ai.name":"Versie zonder AI","no-ai.line":"Een bord voor mensen die zonder AI programmeren, en openbare borden.","night-watch.name":"Nachtwacht","night-watch.line":"Een nachtwaker en een Scrum Master houden de teams bij de les terwijl jij slaapt.","p-more.name":"Al het andere","p-more.line":"Kleinere ideeën die nog op hun beurt wachten.","p-android.name":"Gsm en Android","p-android.line":"Je bord bereiken vanaf je gsm, daarna een eigen Android-app.","p-release.name":"Alpha en verder","p-release.line":"Gesloten alpha, de live site, daarna de bèta.","p-languages.name":"Meer talen","p-languages.line":"Meer dan honderd talen, en een taalbadmodus voor wie een taal leert.","p-engines.name":"Meer AI-engines","p-engines.line":"Kies per agent Claude, Codex of Gemini.","p-pro.name":"Werken als een pro","p-pro.line":"Risicolabels, merge-poorten, incidentkaarten en vangrails.","p-self.name":"Zorg voor jezelf","p-self.line":"Een moe-modus, herinneringen om goed voor jezelf te zorgen, en 4:20.","p-servers.name":"Servers en schaal","p-servers.line":"Globale serverinstellingen, rollen en plannen voor groei.","p-livestream.name":"Extra's voor streamen","p-livestream.line":"Twitch-chat, eigen emoji's en een openbaar live-overzicht."}};
